<script lang="ts">
  import type { Location } from '../../domain/location';
  import type { FacetResponse } from '../../api/FacetsRepository';
  import { dimensionsFromFacets, dimensionsFromLocations, displayValue, type CoverageDimension } from './coverageModel';
  export let localMode = false; export let profile = 'official'; export let releaseId = ''; export let ruleset = ''; export let locations: readonly Location[] = []; export let facets: FacetResponse | undefined = undefined; export let status: 'idle' | 'loading' | 'ready' | 'error' | 'unavailable' = 'idle'; export let error = ''; export let searchActive = false;
  $: dimensions = localMode && facets ? dimensionsFromFacets(facets.dimensions) : dimensionsFromLocations(locations);
  $: context = localMode ? `Eligible public facility records · ${profile} · ${releaseId}` : 'Synthetic demonstration · no live request';
</script>
<section class="coverage-pulse" aria-labelledby="coverage-heading">
  <div class="coverage-heading"><div><p class="eyebrow">{localMode ? 'EVIDENCE COVERAGE' : 'SYNTHETIC COVERAGE'}</p><h2 id="coverage-heading">What this release makes visible</h2></div><span class="coverage-context">{context}</span></div>
  {#if localMode && status === 'loading'}<p class="coverage-status" role="status">Reading release-wide coverage…</p>
  {:else if localMode && (status === 'error' || status === 'unavailable')}<p class="coverage-status coverage-error" role="status">Coverage summary is unavailable for this response. The visible records remain available. {error}</p>
  {:else if localMode && searchActive}<p class="coverage-status" role="note">Coverage dimensions describe the structured filters and selected profile. Free-text search is excluded because this endpoint does not apply it.</p>
  {:else if dimensions.length === 0}<p class="coverage-status" role="status">No coverage dimensions are available for this view.</p>
  {:else}<div class="coverage-dimensions">{#each dimensions as dimension}<section class="coverage-dimension" aria-labelledby={`coverage-${dimension.key}`}><h3 id={`coverage-${dimension.key}`}>{dimension.label}</h3><p>{dimension.note}</p><dl>{#each dimension.values as item}<div><dt>{displayValue(item.value)}</dt><dd>{item.count}</dd></div>{/each}</dl></section>{/each}</div>{/if}
  <p class="coverage-footnote">Counts are eligible public facility projection rows after current suppression. They are not animal counts, story-wide totals, or a measure of suffering. Each dimension is a separate view; values across dimensions must not be added.</p>
  {#if localMode && ruleset}<p class="coverage-release">Pinned to release <strong>{releaseId}</strong> · ruleset <strong>{ruleset}</strong></p>{/if}
</section>
